// Typed access to lib/panel.json, which is generated by src/export_panel.py in the
// BASE-EPHPM-JULIO-2025 repo. Do not edit the JSON by hand.
import raw from "./panel.json"

export type IndicatorFormat = "pct" | "lps" | "ratio" | "num" | "years"

export interface Indicator {
  key: string
  label: string
  format: IndicatorFormat
  /** which direction means a worse situation */
  worse: "up" | "down" | "none"
  description: string
  note?: string
  years: number[]
}

export interface Cluster {
  id: number
  name: string
  description: string
  profile: Record<string, number>
}

export interface Department {
  code: number
  name: string
  geo: string
}

export type Values = Record<string, number | null>
export type NationalRow = Values & { anio: number; n_hogares: number }
export type DeptRow = Values & { anio: number; depto: number; cluster: number | null; n_hogares: number }

interface Panel {
  generated: string
  source: string
  years: number[]
  cluster_years: number[]
  missing_years_note: string
  indicators: Indicator[]
  model: { algorithm: string; k: number; features: string[]; silhouette: number; rows: number }
  clusters: Cluster[]
  departments: Department[]
  national: NationalRow[]
  rows: DeptRow[]
}

export const panel = raw as unknown as Panel

export const YEARS = panel.years
export const LATEST_YEAR = YEARS[YEARS.length - 1]
export const INDICATORS = panel.indicators
export const CLUSTERS = panel.clusters
export const DEPARTMENTS = panel.departments

/** "cluster" is the model's level; any other value is an indicator key. */
export const CLUSTER_METRIC = "cluster"

export const CLUSTER_COLORS = ["#0d9488", "#f59e0b", "#e11d48"]
export const NO_DATA_COLOR = "#94a3b8"

const indicatorMap = new Map(INDICATORS.map((i) => [i.key, i]))
const departmentMap = new Map(DEPARTMENTS.map((d) => [d.code, d]))
const departmentByGeo = new Map(DEPARTMENTS.map((d) => [d.geo, d]))

export const getIndicator = (key: string) => indicatorMap.get(key)!
export const getDepartment = (code: number) => departmentMap.get(code)!

/** Same normalisation as geo_key() in export_panel.py, applied to GADM's NAME_1. */
export function departmentFromGeoName(name: string): Department | undefined {
  const key = name
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/\s+/g, "")
    .toLowerCase()
  return departmentByGeo.get(key)
}

export const nationalRow = (year: number) => panel.national.find((r) => r.anio === year)
export const rowsForYear = (year: number) => panel.rows.filter((r) => r.anio === year)
export const rowsForDepartment = (code: number) => panel.rows.filter((r) => r.depto === code)
export const deptRow = (code: number, year: number) =>
  panel.rows.find((r) => r.depto === code && r.anio === year)

export function formatValue(format: IndicatorFormat, value: number | null | undefined): string {
  if (value === null || value === undefined) return "—"
  switch (format) {
    case "pct":
      return `${(value * 100).toFixed(1)}%`
    case "lps":
      return `L ${Math.round(value).toLocaleString("es-HN")}`
    case "years":
      return `${value.toFixed(1)} años`
    default:
      return value.toFixed(2)
  }
}

/** Change between two values, in the unit that reads naturally for the format. */
export function formatDelta(format: IndicatorFormat, from: number, to: number): string {
  const sign = to >= from ? "+" : "−"
  if (format === "pct") return `${sign}${Math.abs((to - from) * 100).toFixed(1)} pp`
  if (format === "lps") return `${sign}${Math.abs((to / from - 1) * 100).toFixed(0)}%`
  return `${sign}${Math.abs(to - from).toFixed(2)}`
}

const extentCache = new Map<string, [number, number]>()

/** Min and max of an indicator across every department and year, so colours compare across years. */
export function indicatorExtent(key: string): [number, number] {
  const hit = extentCache.get(key)
  if (hit) return hit
  const values = panel.rows.map((r) => r[key]).filter((v): v is number => v !== null && v !== undefined)
  const extent: [number, number] = [Math.min(...values), Math.max(...values)]
  extentCache.set(key, extent)
  return extent
}

const RAMP = [
  [224, 231, 255],
  [129, 140, 248],
  [55, 48, 163],
]

function ramp(t: number): string {
  const x = Math.min(1, Math.max(0, t)) * (RAMP.length - 1)
  const i = Math.min(RAMP.length - 2, Math.floor(x))
  const f = x - i
  const c = RAMP[i].map((a, j) => Math.round(a + (RAMP[i + 1][j] - a) * f))
  return `rgb(${c[0]}, ${c[1]}, ${c[2]})`
}

export const rampCss = `linear-gradient(90deg, ${ramp(0)}, ${ramp(0.5)}, ${ramp(1)})`

/** Fill colour of one department-year for the chosen metric. */
export function colorFor(metric: string, row: DeptRow | undefined): string {
  if (!row) return NO_DATA_COLOR
  if (metric === CLUSTER_METRIC) {
    return row.cluster === null ? NO_DATA_COLOR : CLUSTER_COLORS[row.cluster]
  }
  const v = row[metric]
  if (v === null || v === undefined) return NO_DATA_COLOR
  const [min, max] = indicatorExtent(metric)
  return ramp((v - min) / (max - min))
}

export function labelFor(metric: string, row: DeptRow | undefined): string {
  if (!row) return "Sin datos"
  if (metric === CLUSTER_METRIC) {
    return row.cluster === null ? "Sin nivel este año" : CLUSTERS[row.cluster].name
  }
  return formatValue(getIndicator(metric).format, row[metric])
}

/** Years between the first and last survey that have no published microdata. */
export const GAP_YEARS = (() => {
  const gaps: number[] = []
  for (let y = YEARS[0]; y <= LATEST_YEAR; y++) if (!YEARS.includes(y)) gaps.push(y)
  return gaps
})()

/** Contiguous runs of missing years, e.g. [[2012, 2017], [2020, 2020]]. */
export const GAP_RANGES = GAP_YEARS.reduce<[number, number][]>((acc, y) => {
  const last = acc[acc.length - 1]
  if (last && last[1] === y - 1) last[1] = y
  else acc.push([y, y])
  return acc
}, [])

export const API_URL =
  process.env.NEXT_PUBLIC_API_URL ?? "https://base-ephpm-julio-2025.vercel.app"
